  // ── prompts ──
  server.registerPrompt('browse', { title: 'Browse a site for a goal', description: 'Use the browser service to observe, act, verify, and finalize.', argsSchema: { goal: z.string(), url: z.string().optional() } }, ({ goal, url }) => ({ messages: [{ role: 'user', content: { type: 'text', text: `Goal: ${goal}${url ? `\nStart at: ${url}` : ''}\n\n1. For a supported site, find a matching adapter with sites_search and execute it with site_run.\n2. For other tasks, use tabs_list to reuse or claim an existing tab, then observe → act → verify. navigate_tab reuses that tab; open_tab creates a separate one. Read docs_get when you need API details.\n3. Finish with session_finish, keeping only deliverable/handoff tabs.` } }] }));
